"""Compile and match the small regex subset supported by this version.

Supported syntax (fullmatch only):
  * literals (any Unicode character), concatenation and the empty pattern
  * "." matching any single character, newline included
  * backslash escapes of metacharacters; an escaped reserved char is literal
  * character classes: [abc], [a-z], [^...]; ], -, ^ and \\ are escapable
  * numbered capturing groups: (...), nestable; empty groups are legal
  * postfix quantifiers ? * + {m} {m,} {m,n}, on atoms or whole groups

Alternation, anchors, named groups and backreferences are rejected at
compile time.
"""

from __future__ import annotations

__all__ = ["RegexSyntaxError", "Match", "Pattern", "compile", "fullmatch"]

_INF = float("inf")
_DIGITS = frozenset("0123456789")
_QUANTIFIER_STARTS = frozenset("?*+{")
_SIMPLE_BOUNDS = {"?": (0, 1), "*": (0, _INF), "+": (1, _INF)}


class RegexSyntaxError(ValueError):
    """A pattern could not be compiled.

    ``pos`` is the zero-based offset of the first character at which the
    pattern is invalid; the offset is also included in the error message.
    """

    def __init__(self, message: str, pos: int) -> None:
        self.pos = pos
        super().__init__(f"{message} at position {pos}")


def _error(message: str, pos: int):
    raise RegexSyntaxError(message, pos)


# ---------------------------------------------------------------------------
# Parsing
# ---------------------------------------------------------------------------


def _parse_braces(pattern: str, i: int):
    """Parse a {m}, {m,} or {m,n} quantifier starting at pattern[i] == "{"."""
    start = i
    n = len(pattern)
    j = i + 1
    if j >= n or pattern[j] not in _DIGITS:
        _error("invalid quantifier bounds", start)
    while j < n and pattern[j] in _DIGITS:
        j += 1
    lo = int(pattern[i + 1 : j])
    if j >= n:
        _error("unclosed quantifier bounds", start)
    if pattern[j] == "}":
        return lo, lo, j + 1
    if pattern[j] != ",":
        _error("invalid quantifier bounds", start)
    j += 1
    k = j
    while k < n and pattern[k] in _DIGITS:
        k += 1
    if k == j:
        if k < n and pattern[k] == "}":
            return lo, _INF, k + 1
        _error("invalid quantifier bounds", start)
    hi = int(pattern[j:k])
    if k >= n or pattern[k] != "}":
        _error("invalid quantifier bounds", start)
    if hi < lo:
        _error("quantifier upper bound is smaller than lower bound", start)
    return lo, hi, k + 1


def _parse_class_char(pattern: str, i: int):
    """Read one member character; returns (char, next_index, char_offset)."""
    if pattern[i] == "\\":
        if i + 1 >= len(pattern):
            _error("dangling backslash in character class", i)
        return pattern[i + 1], i + 2, i
    return pattern[i], i + 1, i


def _parse_class(pattern: str, i: int):
    """Parse a character class starting at pattern[i] == "["."""
    start = i
    n = len(pattern)
    i += 1  # consume "["
    negated = False
    if i < n and pattern[i] == "^":
        negated = True
        i += 1
    chars: set[str] = set()
    ranges: list[tuple[str, str]] = []
    members = 0
    while True:
        if i >= n:
            _error("unterminated character class", start)
        if pattern[i] == "]":
            if members == 0:
                _error("empty character class", start)
            i += 1
            break
        lo, i, lo_pos = _parse_class_char(pattern, i)
        members += 1
        if i + 1 < n and pattern[i] == "-" and pattern[i + 1] != "]":
            hi, i, _ = _parse_class_char(pattern, i + 1)
            members += 1
            if lo > hi:
                _error(f"reversed character range {lo!r}-{hi!r}", lo_pos)
            ranges.append((lo, hi))
        else:
            chars.add(lo)
    atom = ("cls", (negated, frozenset(chars), tuple(ranges)))
    return atom, i


class _GroupCounter:
    """Allocates 1-based group numbers in left-parenthesis order."""

    __slots__ = ("next",)

    def __init__(self) -> None:
        self.next = 1

    def alloc(self) -> int:
        gid = self.next
        self.next += 1
        return gid


def _parse_atom(pattern: str, i: int, groups: _GroupCounter):
    c = pattern[i]
    if c == "\\":
        if i + 1 >= len(pattern):
            _error("dangling backslash", i)
        return ("lit", pattern[i + 1]), i + 2
    if c == ".":
        return ("any", None), i + 1
    if c == "[":
        return _parse_class(pattern, i)
    if c == "(":
        return _parse_group(pattern, i, groups)
    if c in "?*+":
        _error("quantifier with no preceding atom", i)
    if c == "{":
        # Validate the bounds shape first, but a brace quantifier still
        # needs an atom in front of it.
        _parse_braces(pattern, i)
        _error("quantifier with no preceding atom", i)
    if c == ")":
        _error("unbalanced parenthesis", i)
    if c == "|":
        _error("alternation is not supported", i)
    if c == "^" or c == "$":
        _error("anchors are not supported", i)
    # Bare "]" and "}" are ordinary literal characters.
    return ("lit", c), i + 1


def _parse_group(pattern: str, i: int, groups: _GroupCounter):
    """Parse a capturing group starting at pattern[i] == "("."""
    start = i
    gid = groups.alloc()
    pieces, i = _parse_sequence(pattern, i + 1, groups)
    if i >= len(pattern) or pattern[i] != ")":
        _error("unbalanced parenthesis", start)
    return ("grp", (gid, tuple(pieces))), i + 1


def _parse_sequence(pattern: str, i: int, groups: _GroupCounter):
    """Parse pieces up to the end of the pattern or an unmatched ")"."""
    pieces = []
    n = len(pattern)
    while i < n and pattern[i] != ")":
        atom, i = _parse_atom(pattern, i, groups)
        lo, hi = 1, 1
        if i < n and pattern[i] in _SIMPLE_BOUNDS:
            lo, hi = _SIMPLE_BOUNDS[pattern[i]]
            i += 1
            if i < n and pattern[i] in _QUANTIFIER_STARTS:
                _error("multiple quantifiers on one atom", i)
        elif i < n and pattern[i] == "{":
            lo, hi, i = _parse_braces(pattern, i)
            if i < n and pattern[i] in _QUANTIFIER_STARTS:
                _error("multiple quantifiers on one atom", i)
        pieces.append((atom, lo, hi))
    return pieces, i


def _parse(pattern: str):
    groups = _GroupCounter()
    pieces, i = _parse_sequence(pattern, 0, groups)
    if i < len(pattern):  # the only character that stops a sequence is ")"
        _error("unbalanced parenthesis", i)
    return tuple(pieces), groups.next - 1


# ---------------------------------------------------------------------------
# Matching
#
# A greedy backtracking NFA simulated with an explicit frame stack, so the
# recursion depth (pattern nesting and repetition counts) is bounded by
# heap memory rather than the Python call stack.
#
# Two kinds of frames enumerate the ways a sequence can finish, always in
# greedy order (longest match first):
#
#   S -- one sequence of pieces.  Plain (single-character) atoms are
#        stretched greedily; their choice points (piece index, start
#        position, tried count) live in ``alts`` and are shortened on
#        backtrack.  A group piece hands control to a G frame.
#
#   G -- one group piece (``(sub){lo,hi}``) at a fixed repetition number.
#        It asks a child S frame for the next end position of one ``sub``
#        attempt; a successful attempt that advanced pushes another G frame
#        for one more repetition, an empty successful attempt stops
#        expansion, and a failed / exhausted attempt settles with the tail
#        (pieces after the group) once the minimum is met.
#
# Frames yield end positions to their parent frame; a yielded frame stays
# alive in the parent's custody and is driven again when the parent needs
# its next alternative.  Group captures live in one flat array; a G frame
# snapshots its own group's slot on entry and restores it on every backtrack
# and on exhaustion, so captures of abandoned attempts never leak, including
# captures made by nested groups (their G frames restore themselves).
# ---------------------------------------------------------------------------


def _atom_matches(atom, ch: str) -> bool:
    kind = atom[0]
    if kind == "lit":
        return ch == atom[1]
    if kind == "any":
        return True
    negated, members, ranges = atom[1]
    found = ch in members
    if not found:
        for lo, hi in ranges:
            if lo <= ch <= hi:
                found = True
                break
    return (not found) if negated else found


# S frame layout: ["S", pieces, k, pos, alts, phase, susp]
#   phase: "run"     working through the sequence
#          "end"     yielded after reaching the last piece (resume = undo)
#          "waitG"   child G frame running
#          "propG"   a child G result is being yielded to our own parent
_S_RUN, _S_END, _S_WAIT_G, _S_PROP_G = "run", "end", "waitG", "propG"

# G frame layout:
# ["G", pieces, k, pos, count, phase, sub_frame, tail_frame, old_capture]
#   phase: "sub"     waiting for the next sub-sequence attempt
#          "ext"     waiting for the expansion G frame
#          "zero"    waiting for the tail after an empty successful attempt
#          "settle"  waiting for the tail while settling at this count
#          "p_*"     a result from the corresponding child is propagating
_G_INIT = "init"
_G_SUB, _G_EXT, _G_ZERO, _G_SETTLE = "sub", "ext", "zero", "settle"
_G_P_EXT, _G_P_ZERO, _G_P_SETTLE = "p_ext", "p_zero", "p_settle"


class _Runner:
    def __init__(self, program, text: str) -> None:
        self.pieces, self.ngroups = program
        self.text = text
        self.n = len(text)
        # Group 0 is unused; a slot is None while the group has not (yet)
        # participated in the attempt under exploration.
        self.caps: list = [None] * (self.ngroups + 1)
        self.stack: list = []

    # -- frame constructors -------------------------------------------------

    def _seq_frame(self, pieces, pos: int):
        return ["S", pieces, 0, pos, [], _S_RUN, None]

    def _group_frame(self, pieces, k: int, pos: int, count: int):
        return ["G", pieces, k, pos, count, _G_INIT, None, None, None]

    # -- S-frame backtracking ----------------------------------------------

    def _s_backtrack(self, f):
        """Shorten the most recent plain-atom choice; fail if none remains."""
        pieces, alts = f[1], f[4]
        while alts:
            j, start, count = alts[-1]
            lo = pieces[j][1]
            count -= 1
            if count >= lo:
                alts[-1] = (j, start, count)
                f[2] = j + 1
                f[3] = start + count
                f[5] = _S_RUN
                return "again"
            alts.pop()
        return "fail"

    # -- one dispatch step; returns ("push", frame), ("yield", pos),
    #    "fail" or "again" (re-dispatch the same top frame) ----------------

    def _step(self, f, event):
        tag = f[0]

        if tag == "S":
            _, pieces, k, pos, alts, phase, susp = f
            if phase == _S_PROP_G:
                # Our propagated child result was rejected by our parent:
                # let the G frame offer its next alternative.
                f[5] = _S_WAIT_G
                return ("push", susp)
            if phase == _S_WAIT_G:
                if event[0] == "yield":
                    f[6] = event[2]       # keep the G frame for resumption
                    f[5] = _S_PROP_G
                    return ("yield", event[1])
                f[5] = _S_RUN            # the group piece has no alternative
                action = self._s_backtrack(f)
                return action if action == "fail" else "again"
            if phase == _S_END:
                return self._s_backtrack(f)
            # phase == "run"
            while True:
                if k == len(pieces):
                    f[5] = _S_END
                    return ("yield", pos)
                atom, lo, hi = pieces[k]
                if atom[0] != "grp":
                    start = pos
                    count = 0
                    while (
                        count < hi
                        and pos < self.n
                        and _atom_matches(atom, self.text[pos])
                    ):
                        pos += 1
                        count += 1
                    if count < lo:
                        f[2], f[3] = k, pos
                        action = self._s_backtrack(f)
                        return action if action == "fail" else "again"
                    alts.append((k, start, count))
                    k += 1
                    f[2], f[3] = k, pos
                    continue
                # Group piece: enumerate it through a G frame.
                f[5] = _S_WAIT_G
                f[6] = None
                return ("push", self._group_frame(pieces, k, pos, 0))

        # tag == "G"
        _, pieces, k, pos, count, phase, subf, tailf, oldcap = f
        gid, sub = pieces[k][0][1]
        lo, hi = pieces[k][1], pieces[k][2]

        if phase == _G_INIT:
            f[8] = self.caps[gid]
            if count < hi:
                f[5] = _G_SUB
                return ("push", self._seq_frame(sub, pos))
            phase = _G_SETTLE  # expansion was stopped before entering

        if phase == _G_SUB:
            if event[0] == "yield":
                sub_end = event[1]
                f[6] = event[2]          # S frame offering sub_end
                self.caps[gid] = (pos, sub_end)
                if sub_end > pos:
                    f[5] = _G_EXT
                    return ("push",
                            self._group_frame(pieces, k, sub_end, count + 1))
                # Successful but empty: the attempt counts, then expansion
                # of this repetition must stop.
                if count + 1 >= lo:
                    f[5] = _G_ZERO
                    return ("push", self._seq_frame(pieces[k + 1 :], sub_end))
                self.caps[gid] = f[8]
                return ("push", f[6])    # ask sub for its next attempt
            # sub can no longer match at this position: settle if allowed
            self.caps[gid] = f[8]
            if count >= lo:
                f[5] = _G_SETTLE
                return ("push", self._seq_frame(pieces[k + 1 :], pos))
            return "fail"

        if phase == _G_EXT:
            if event[0] == "yield":
                f[7] = event[2]          # expansion G frame offering a result
                f[5] = _G_P_EXT
                return ("yield", event[1])
            # Every continuation of one more repetition failed: revert that
            # repetition's capture and offer the next shorter sub attempt.
            self.caps[gid] = f[8]
            f[5] = _G_SUB
            return ("push", subf)

        if phase == _G_ZERO:
            if event[0] == "yield":
                f[7] = event[2]
                f[5] = _G_P_ZERO
                return ("yield", event[1])
            self.caps[gid] = f[8]
            f[5] = _G_SUB
            return ("push", subf)

        if phase == _G_SETTLE:
            if event[0] == "yield":
                f[7] = event[2]
                f[5] = _G_P_SETTLE
                return ("yield", event[1])
            self.caps[gid] = f[8]
            return "fail"

        # A propagating result was rejected by our parent: resume whichever
        # child produced it so it can offer its next alternative.
        resume = {
            _G_P_EXT: (_G_EXT, 7),
            _G_P_ZERO: (_G_ZERO, 7),
            _G_P_SETTLE: (_G_SETTLE, 7),
        }[phase]
        f[5] = resume[0]
        return ("push", f[resume[1]])

    # -- driver -------------------------------------------------------------

    def run(self):
        root = self._seq_frame(self.pieces, 0)
        self.stack = [root]
        event = ("drive",)
        while True:
            action = self._step(self.stack[-1], event)
            if action == "again":
                event = ("drive",)
                continue
            kind = action[0]
            if kind == "push":
                self.stack.append(action[1])
                event = ("drive",)
                continue
            if kind == "yield":
                end = action[1]
                yielded = self.stack.pop()
                if not self.stack:
                    if end == self.n:
                        return list(self.caps)  # independent copy
                    # Rejected by the full-match boundary: keep exploring.
                    self.stack.append(yielded)
                    event = ("drive",)
                    continue
                event = ("yield", end, yielded)
                continue
            # fail
            self.stack.pop()
            if not self.stack:
                return None
            event = ("fail",)


def _run(program, text: str):
    return _Runner(program, text).run()


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------


class Match:
    """A successful full match; the matched span is always the whole text."""

    __slots__ = ("string", "_spans")

    def __init__(self, text: str, spans) -> None:
        self.string = text
        # spans[g] is (start, end) for a participating group, else None.
        self._spans = tuple(spans)

    def _check(self, index: int) -> int:
        if not isinstance(index, int) or isinstance(index, bool):
            raise TypeError("group index must be an integer")
        if index < 0 or index >= len(self._spans):
            raise IndexError("no such group")
        return index

    def group(self, index: int = 0):
        index = self._check(index)
        if index == 0:
            return self.string
        span = self._spans[index]
        return None if span is None else self.string[span[0] : span[1]]

    def groups(self) -> tuple:
        return tuple(
            None if span is None else self.string[span[0] : span[1]]
            for span in self._spans[1:]
        )

    def start(self, index: int = 0) -> int:
        index = self._check(index)
        if index == 0:
            return 0
        span = self._spans[index]
        return -1 if span is None else span[0]

    def end(self, index: int = 0) -> int:
        index = self._check(index)
        if index == 0:
            return len(self.string)
        span = self._spans[index]
        return -1 if span is None else span[1]

    def span(self, index: int = 0) -> tuple[int, int]:
        index = self._check(index)
        if index == 0:
            return (0, len(self.string))
        span = self._spans[index]
        return (-1, -1) if span is None else (span[0], span[1])

    def __repr__(self) -> str:
        return f"<Match {self.string!r}>"


class Pattern:
    """A compiled pattern, reusable across any number of texts."""

    __slots__ = ("pattern", "_program")

    def __init__(self, pattern: str, program) -> None:
        self.pattern = pattern
        self._program = program

    def fullmatch(self, text: str):
        if not isinstance(text, str):
            raise TypeError("text must be a str")
        spans = _run(self._program, text)
        if spans is None:
            return None
        spans[0] = (0, len(text))
        return Match(text, spans)

    def __repr__(self) -> str:
        return f"<Pattern {self.pattern!r}>"


def compile(pattern: str) -> Pattern:
    """Compile a pattern string into a reusable :class:`Pattern`."""
    if not isinstance(pattern, str):
        raise TypeError("pattern must be a str")
    pieces, ngroups = _parse(pattern)
    return Pattern(pattern, (pieces, ngroups))


def fullmatch(pattern: str, text: str):
    """Compile ``pattern`` and match it against the whole of ``text``."""
    return compile(pattern).fullmatch(text)

