        if phase == _G_SUB and event[0] == "drive":
            # count is the number of repetitions already consumed; another
            # one is still allowed only while count < hi.
            if count < hi:
                return ("push", self._seq_frame(sub, pos))
            # Upper bound reached at this position: settling means "take no
            # further repetition here".  The capture still belongs to the
            # previous repetition (or to before the group if count == 0).
            f[5] = _G_SETTLE_DONE
            return ("yield", pos)

        if phase == _G_SUB:
            if event[0] == "yield":
                sub_end = event[1]
                f[6] = event[2]          # sub S frame offering sub_end
                self._capture(gid, (pos, sub_end))  # this repetition
                if sub_end == pos:
                    # Matched the empty string: keep this capture, stop the
                    # expansion outright (the lower bound is waived for an
                    # empty match) and offer the position once.
                    f[5] = _G_ZERO
                    return ("yield", sub_end)
                if count + 1 < hi:
                    # Greedily try one more repetition first.
                    child = self._group_frame(pieces, k, sub_end, count + 1)
                    f[7] = child
                    f[5] = _G_EXT
                    return ("push", child)
                # This was the last allowed repetition; settle on it.  A
                # shorter sub match is still a valid alternative.
                return yield_settle(sub_end, _G_SETTLE_MORE)
            # sub offers no end position here.
            if count >= lo:
                # Settle without another repetition; discard everything this
                # enumeration captured so the group shows its prior state.
                self._rollback(mark)
                f[5] = _G_SETTLE_DONE
                return ("yield", pos)
            return "fail"

        if phase == _G_EXT:
            if event[0] == "yield":
                f[5] = _G_EXT  # resume the same child for its next position
                return ("yield", event[1])
            # No way to extend further: settle with the repetition captured
            # so far (its capture survived the child's rollback), then let
            # sub offer shorter matches.
            if count + 1 >= lo:
                f[5] = _G_SETTLE_MORE
                return ("yield", self._sub_end())
            f[5] = _G_SUB
            return ("push", subf)

        if phase == _G_SETTLE:
            mode = f[5]
            if event[0] == "yield":
                # A position we offered was accepted upwards; remember how
                # to produce the next one and propagate the same position.
                f[5] = mode  # already set
                return ("yield", event[1]) if False else self._propagate(f, event)
            if mode == _G_SETTLE_MORE:
                # Offered settlement was rejected: ask sub for a shorter end.
                f[5] = _G_SUB
                return ("push", subf)
            return "fail"

        if phase == _G_ZERO:
            if event[0] == "yield":
                return self._propagate(f, event)
            return "fail"

    def _sub_end(self):
        # The position currently captured for this group is the latest
        # repetition; its end is exactly where settling stops.
        raise NotImplementedError

    def _propagate(self, f, event):
        return ("yield", event[1])

