        # by taking no further repetition if the minimum is already met,
        # otherwise the whole enumeration fails; in both cases captures
        # return to the state on entry.
        self._restore(entry)
        if count >= lo:
            f[5] = _G_FINAL
            return ("yield", base)
        return "fail"
